// Minimal pure-JS reimplementation of the subset of the Python `bidict`
// package used by test8.py. No JavaScript `Map`: forward and inverse
// indexes are plain null-prototype objects, insertion order is kept in a
// parallel array of keys.

export class ValueDuplicationError extends Error {
  constructor(value) {
    super(String(value));
    this.name = 'ValueDuplicationError';
    this.value = value;
  }
}

export class KeyAndValueDuplicationError extends Error {
  constructor(key, value) {
    super(`(${key}, ${value})`);
    this.name = 'KeyAndValueDuplicationError';
    this.key = key;
    this.value = value;
  }
}

export class KeyLookupError extends Error {
  constructor(key) {
    super(String(key));
    this.name = 'KeyLookupError';
    this.key = key;
  }
}

const hasOwn = (obj, prop) => Object.prototype.hasOwnProperty.call(obj, prop);

export class Bidict {
  constructor() {
    // forward index: key (string) -> value (bigint)
    this._fwd = Object.create(null);
    // inverse index: String(value) -> key (string); values are BigInt so
    // their decimal string form is a unique, collision-free object key.
    this._inv = Object.create(null);
    // insertion order of keys
    this._order = [];
  }

  set(key, value) {
    if (hasOwn(this._fwd, key)) {
      const oldValue = this._fwd[key];
      if (oldValue === value) {
        // same key + same value: silent no-op
        return;
      }
      const valueKey = String(value);
      if (hasOwn(this._inv, valueKey)) {
        // existing key being set to a value held by a different key
        throw new KeyAndValueDuplicationError(key, value);
      }
      // overwrite in place, keeping the original insertion position
      delete this._inv[String(oldValue)];
      this._inv[valueKey] = key;
      this._fwd[key] = value;
      return;
    }
    const valueKey = String(value);
    if (hasOwn(this._inv, valueKey)) {
      // new key with a value already present under another key
      throw new ValueDuplicationError(value);
    }
    this._fwd[key] = value;
    this._inv[valueKey] = key;
    this._order.push(key);
  }

  get(key) {
    if (!hasOwn(this._fwd, key)) {
      throw new KeyLookupError(key);
    }
    return this._fwd[key];
  }

  invGet(value) {
    const valueKey = String(value);
    if (!hasOwn(this._inv, valueKey)) {
      throw new KeyLookupError(value);
    }
    return this._inv[valueKey];
  }

  entries() {
    return this._order.map((key) => [key, this._fwd[key]]);
  }
}

import { Bidict, ValueDuplicationError, KeyAndValueDuplicationError, KeyLookupError } from '/output/lib/bidict.mjs';

let failures = 0;
const eq = (a, b) => JSON.stringify(a, (k, v) => typeof v === 'bigint' ? v.toString() + 'n' : v) === JSON.stringify(b, (k, v) => typeof v === 'bigint' ? v.toString() + 'n' : v);
function check(name, fn) {
  try { fn(); console.log('ok -', name); }
  catch (e) { failures++; console.log('FAIL -', name, '::', e.message); }
}
function assert(cond, msg) { if (!cond) throw new Error(msg); }

check('basic set/get/invGet + insertion order', () => {
  const b = new Bidict();
  b.set('i', 55n); b.set('c', 95n); b.set('t', 92n);
  assert(b.get('i') === 55n, 'get i');
  assert(b.invGet(95n) === 'c', 'invGet 95');
  assert(eq(b.entries(), [['i', 55n], ['c', 95n], ['t', 92n]]), 'order');
});

check('same key + same value is silent no-op', () => {
  const b = new Bidict();
  b.set('a', 1n); b.set('b', 2n);
  b.set('a', 1n);
  assert(eq(b.entries(), [['a', 1n], ['b', 2n]]), 'entries unchanged');
});

check('new key + existing value -> ValueDuplicationError with .value', () => {
  const b = new Bidict();
  b.set('i', 55n); b.set('c', 95n);
  let err;
  try { b.set('x', 55n); } catch (e) { err = e; }
  assert(err instanceof ValueDuplicationError, 'class');
  assert(err.value === 55n, 'value stored');
  assert(eq(b.entries(), [['i', 55n], ['c', 95n]]), 'no mutation');
});

check('existing key + value of different key -> KeyAndValueDuplicationError', () => {
  const b = new Bidict();
  b.set('a', 1n); b.set('b', 999n);
  let err;
  try { b.set('a', 999n); } catch (e) { err = e; }
  assert(err instanceof KeyAndValueDuplicationError, 'class');
  assert(err.key === 'a' && err.value === 999n, 'key/value stored');
  assert(eq(b.entries(), [['a', 1n], ['b', 999n]]), 'no mutation');
});

check('overwrite keeps insertion position, inverse index updated', () => {
  const b = new Bidict();
  b.set('i', 55n); b.set('c', 95n); b.set('t', 92n);
  b.set('i', 999n);
  assert(eq(b.entries(), [['i', 999n], ['c', 95n], ['t', 92n]]), 'position kept');
  let err;
  try { b.invGet(55n); } catch (e) { err = e; }
  assert(err instanceof KeyLookupError, 'old value removed from inverse');
  assert(b.invGet(999n) === 'i', 'new inverse');
});

check('missing key/value lookups throw KeyLookupError with .key', () => {
  const b = new Bidict();
  let e1, e2;
  try { b.get('nope'); } catch (e) { e1 = e; }
  try { b.invGet(2n); } catch (e) { e2 = e; }
  assert(e1 instanceof KeyLookupError && e1.key === 'nope', 'get');
  assert(e2 instanceof KeyLookupError && e2.key === 2n, 'invGet');
});

check('large BigInt values stay exact', () => {
  const b = new Bidict();
  const big = 100000000000000000000n;
  b.set('k', big);
  assert(b.get('k') === big, 'get big');
  assert(b.invGet(big) === 'k', 'inv big');
});

check('hostile keys (__proto__, constructor) work', () => {
  const b = new Bidict();
  b.set('__proto__', 1n); b.set('constructor', 2n);
  assert(b.get('__proto__') === 1n, 'proto key');
  assert(b.invGet(2n) === 'constructor', 'constructor inv');
  assert(eq(b.entries(), [['__proto__', 1n], ['constructor', 2n]]), 'order');
});

check('overwrite to value held by different key still throws after prior overwrites', () => {
  const b = new Bidict();
  b.set('a', 1n); b.set('b', 2n);
  b.set('a', 5n); // now a->5, b->2
  let err;
  try { b.set('a', 2n); } catch (e) { err = e; }
  assert(err instanceof KeyAndValueDuplicationError, 'throws');
  assert(b.invGet(5n) === 'a', 'a still 5');
});

console.log(failures === 0 ? 'ALL PASSED' : failures + ' FAILURES');
process.exitCode = failures === 0 ? 0 : 1;
